package docs

import (
	"testing"

	"github.com/project-kessel/starlark-unified-schema/internal/lang"
	"github.com/project-kessel/starlark-unified-schema/internal/util"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// schemaDir is the real schema tree, relative to this package.
const schemaDir = "../../../schema"

// apiReferencePath is the committed reference regenerated by `make docs`.
const apiReferencePath = schemaDir + "/API.md"

func newTestLoader(t *testing.T) (*lang.Loader, *lang.InmemorySourceFileReader) {
	t.Helper()

	reader := lang.NewInMemorySourceFileReader("schema", schemaDir)
	return lang.NewLoaderForReader("schema", reader), reader
}

func moduleByPath(t *testing.T, ref *Reference, path string) Module {
	t.Helper()

	for _, module := range ref.Modules {
		if module.Path == path {
			return module
		}
	}
	t.Fatalf("no module %s in reference (have %v)", path, modulePaths(ref))
	return Module{}
}

func modulePaths(ref *Reference) []string {
	paths := make([]string, 0, len(ref.Modules))
	for _, module := range ref.Modules {
		paths = append(paths, module.Path)
	}
	return paths
}

func symbolNames(module Module) []string {
	names := make([]string, 0, len(module.Symbols))
	for _, symbol := range module.Symbols {
		names = append(names, symbol.Name)
	}
	return names
}

func TestGenerateDocumentsPublicFunctionsOnly(t *testing.T) {
	loader, reader := newTestLoader(t)
	util.AddFile(t, reader, "dsl.star", `
_module_doc = """What this module is for."""

def public(a, b=1):
    """Does a public thing."""
    return a

def _private(a):
    """Not loadable, so not documented."""
    return a

aConstant = ["x", "y"]
`)

	ref, err := Generate(loader)
	require.NoError(t, err)

	module := moduleByPath(t, ref, "dsl.star")
	assert.Equal(t, []string{"public"}, symbolNames(module))
	assert.Equal(t, "What this module is for.", module.Doc)
	assert.Equal(t, "public(a, b=1)", module.Symbols[0].Signature)
	assert.Equal(t, "Does a public thing.", module.Symbols[0].Doc)
}

// load()ed names bind file-locally rather than becoming globals of the
// importing module. The generator reads globals to find what a module defines,
// so flipping FileOptions.LoadBindsGlobally would make every schema file
// re-document the whole DSL.
func TestGenerateExcludesLoadedNames(t *testing.T) {
	loader, reader := newTestLoader(t)
	util.AddFile(t, reader, "a.star", `
def from_a(x):
    return x
`)
	util.AddFile(t, reader, "b.star", `
load("a.star", "from_a")

def from_b(y):
    return from_a(y)
`)

	ref, err := Generate(loader)
	require.NoError(t, err)

	assert.Equal(t, []string{"from_b"}, symbolNames(moduleByPath(t, ref, "b.star")))
}

// Schema files bind the accessor closures that extensions/*.star wrappers
// return. Those are values defined in another file, not API this module offers.
func TestGenerateExcludesFunctionsDefinedElsewhere(t *testing.T) {
	loader, reader := newTestLoader(t)
	util.AddFile(t, reader, "wrappers.star", `
def make_accessor(name):
    def accessor(target):
        return target
    return accessor
`)
	util.AddFile(t, reader, "consumer.star", `
load("wrappers.star", "make_accessor")

some_permission = make_accessor("view")
`)

	ref, err := Generate(loader)
	require.NoError(t, err)

	assert.NotContains(t, modulePaths(ref), "consumer.star")
	assert.Equal(t, []string{"make_accessor"}, symbolNames(moduleByPath(t, ref, "wrappers.star")))
}

func TestGenerateSkipsModulesWithoutPublicFunctions(t *testing.T) {
	loader, reader := newTestLoader(t)
	util.AddFile(t, reader, "data.star", `
host = {"name": "a value"}
`)
	util.AddFile(t, reader, "dsl.star", `
def documented():
    return 1
`)

	ref, err := Generate(loader)
	require.NoError(t, err)

	assert.Equal(t, []string{"dsl.star"}, modulePaths(ref))
}

func TestGenerateFailsOnBrokenModule(t *testing.T) {
	loader, reader := newTestLoader(t)
	util.AddFile(t, reader, "broken.star", `fail("deliberate")`)

	_, err := Generate(loader)

	require.Error(t, err)
	assert.Contains(t, err.Error(), "broken.star")
}

func TestGenerateIsDeterministic(t *testing.T) {
	render := func() string {
		loader, reader := newTestLoader(t)
		for _, name := range []string{"a.star", "b.star", "c.star"} {
			util.AddFile(t, reader, name, `
def second(): pass
def first(): pass
def third(): pass
`)
		}

		ref, err := Generate(loader)
		require.NoError(t, err)
		return Markdown(ref)
	}

	assert.Equal(t, render(), render())
}

// Symbols read in source order, which groups related constructors together far
// better than alphabetical order does.
func TestGenerateOrdersSymbolsBySourcePosition(t *testing.T) {
	loader, reader := newTestLoader(t)
	util.AddFile(t, reader, "dsl.star", `
def zebra(): pass
def apple(): pass
def mango(): pass
`)

	ref, err := Generate(loader)
	require.NoError(t, err)

	assert.Equal(t, []string{"zebra", "apple", "mango"}, symbolNames(moduleByPath(t, ref, "dsl.star")))
}

func TestGenerateDocumentsBuiltins(t *testing.T) {
	loader, _ := newTestLoader(t)

	ref, err := Generate(loader)
	require.NoError(t, err)

	names := make([]string, 0, len(ref.Builtins))
	for _, builtin := range ref.Builtins {
		assert.NotEmpty(t, builtin.Signature, "%s has no signature", builtin.Name)
		assert.NotEmpty(t, builtin.Doc, "%s has no doc", builtin.Name)
		names = append(names, builtin.Name)
	}

	assert.Equal(t, []string{"call_ksl_extension", "println", "struct"}, names)
}
